def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find each solid 2x2 square of color 2.
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2
                   for rr in (r, r + 1)
                   for cc in (c, c + 1)):
                # Diagonal cells around the square: NW, NE, SW, SE.
                positions = [
                    (r - 1, c - 1, -1, -1),  # NW ray
                    (r - 1, c + 2, -1,  1),  # NE ray
                    (r + 2, c - 1,  1, -1),  # SW ray
                    (r + 2, c + 2,  1,  1),  # SE ray
                ]
                source_colors = []
                for rr, cc, _, _ in positions:
                    source_colors.append(
                        grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else 0
                    )

                # Colors rotate between the four diagonal rays.
                ray_colors = [
                    source_colors[2],
                    source_colors[0],
                    source_colors[3],
                    source_colors[1],
                ]

                for (rr, cc, dr, dc), color in zip(positions, ray_colors):
                    while 0 <= rr < h and 0 <= cc < w:
                        if color:
                            out[rr][cc] = color
                        rr += dr
                        cc += dc

    return out
